"""K-means clustering on the proximity representation; NMI evaluation."""
import numpy as np
from sklearn.cluster import KMeans
from sklearn.metrics import normalized_mutual_info_score

from src.proximity_kernel import build_representation


def evaluate_nbins(Z, y, K, seeds, n_init=10):
    scores = []
    for s in seeds:
        km = KMeans(n_clusters=K, init="k-means++", n_init=n_init, random_state=s)
        labels = km.fit_predict(Z)
        scores.append(float(normalized_mutual_info_score(y, labels)))
    return {
        "mean": float(np.mean(scores)),
        "std": float(np.std(scores)),
        "per_seed": scores,
    }


def search_nbins(X, y, K, nbins_grid, seeds, n_init=10):
    results = {}
    diags = {}
    for nb in nbins_grid:
        Z, diag = build_representation(X, nb)
        results[nb] = evaluate_nbins(Z, y, K, seeds, n_init=n_init)
        diags[nb] = diag
    best_nb = max(nbins_grid, key=lambda nb: results[nb]["mean"])
    return best_nb, results, diags
